import { useState } from "react";
import {
  Mail,
  Lock,
  Eye,
  EyeOff,
  ArrowRight,
  ChevronLeft
} from 'lucide-react';
import StudentDashboard from "../StudentDashboard";
import MentorDashboard from "../MentorDashboard";
import PlacementDashboard from "../PlacementDashboard";

const ProfessionalLogin = () => {
  const [selectedUserType, setSelectedUserType] = useState('');
  const [showLogin, setShowLogin] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [loginData, setLoginData] = useState({
    email: '',
    password: ''
  });
  const [loginError, setLoginError] = useState('');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authenticatedUser, setAuthenticatedUser] = useState(null);

  const VALID_CREDENTIALS = {
    'student': { email: 'student@college.edu', password: 'student123' },
    'mentor': { email: 'mentor@college.edu', password: 'mentor123' },
    'placement-cell': { email: 'placement@college.edu', password: 'placement123' }
  };

  const userTypes = [
    {
      id: 'student',
      title: 'Student',
      description: 'Access your placement dashboard'
    },
    {
      id: 'mentor',
      title: 'Mentor',
      description: 'Guide and review student applications'
    },
    {
      id: 'placement-cell',
      title: 'Placement Cell',
      description: 'Manage campus recruitment'
    }
  ];

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoginError('');
    setIsLoading(true);

    const creds = VALID_CREDENTIALS[selectedUserType];

    setTimeout(() => {
      if (loginData.email === creds.email && loginData.password === creds.password) {
        setIsAuthenticated(true);
        setAuthenticatedUser({
          email: loginData.email,
          userType: selectedUserType,
          name: selectedUserType.charAt(0).toUpperCase() + selectedUserType.slice(1)
        });
      } else {
        setLoginError('Invalid email or password. Please try again.');
      }
      setIsLoading(false);
    }, 800);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setAuthenticatedUser(null);
    setSelectedUserType('');
    setShowLogin(false);
    setLoginData({ email: '', password: '' });
    setLoginError('');
  };

  if (isAuthenticated && authenticatedUser) {
    if (authenticatedUser.userType === 'student') {
      return <StudentDashboard onLogout={handleLogout} />;
    } else if (authenticatedUser.userType === 'mentor') {
      return <MentorDashboard onLogout={handleLogout} />;
    } else if (authenticatedUser.userType === 'placement-cell') {
      return <PlacementDashboard onLogout={handleLogout} />;
    }
  }

  if (showLogin && selectedUserType) {
    const currentUserType = userTypes.find(ut => ut.id === selectedUserType);
    const Icon = currentUserType.icon;
    const credentials = VALID_CREDENTIALS[selectedUserType];

    return (
      <div className="min-h-screen bg-white flex">
        {/* Left Side - Login Form */}
        <div className="flex-1 flex items-center justify-center p-8">
          <div className="w-full max-w-md">
            <button
              onClick={() => {
                setShowLogin(false);
                setSelectedUserType('');
                setLoginData({ email: '', password: '' });
                setLoginError('');
              }}
              className="mb-8 text-sm font-medium text-neutral-600 hover:text-neutral-900 transition-colors flex items-center space-x-2"
            >
              <ArrowRight className="h-4 w-4 rotate-180" />
              <span>Back</span>
            </button>

            <div className="mb-8">
              <div className={`inline-flex p-3 rounded-2xl bg-gradient-to-br ${currentUserType.gradient} mb-4`}>
                <Icon className="h-8 w-8 text-white" />
              </div>
              <h1 className="text-3xl font-bold text-neutral-900 mb-2">
                {currentUserType.title} Login
              </h1>
              <p className="text-neutral-600">
                Welcome back! Please enter your credentials.
              </p>
            </div>

            <form onSubmit={handleLogin} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-neutral-700 mb-2">
                  Email Address
                </label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-neutral-400" />
                  <input
                    type="email"
                    required
                    value={loginData.email}
                    onChange={(e) => setLoginData({ ...loginData, email: e.target.value })}
                    className="w-full pl-10 pr-4 py-3 bg-white border border-neutral-300 rounded-xl text-neutral-900 placeholder-neutral-400 focus:outline-none focus:border-blue-600 focus:ring-2 focus:ring-blue-100 transition-all"
                    placeholder="you@college.edu"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-neutral-700 mb-2">
                  Password
                </label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-neutral-400" />
                  <input
                    type={showPassword ? "text" : "password"}
                    required
                    value={loginData.password}
                    onChange={(e) => setLoginData({ ...loginData, password: e.target.value })}
                    className="w-full pl-10 pr-12 py-3 bg-white border border-neutral-300 rounded-xl text-neutral-900 placeholder-neutral-400 focus:outline-none focus:border-blue-600 focus:ring-2 focus:ring-blue-100 transition-all"
                    placeholder="••••••••"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-neutral-400 hover:text-neutral-600 transition-colors"
                  >
                    {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                  </button>
                </div>
              </div>

              {loginError && (
                <div className="p-3 bg-red-50 border border-red-200 rounded-xl">
                  <p className="text-sm font-medium text-red-700">{loginError}</p>
                </div>
              )}

              <div className="bg-blue-50 border border-blue-200 rounded-xl p-3">
                <p className="text-xs font-medium text-blue-900 mb-1">Demo Credentials:</p>
                <p className="text-xs text-blue-700">Email: {credentials.email}</p>
                <p className="text-xs text-blue-700">Password: {credentials.password}</p>
              </div>

              <button
                type="submit"
                disabled={isLoading}
                className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-semibold py-3 rounded-xl transition-all shadow-sm hover:shadow-md disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2"
              >
                {isLoading ? (
                  <>
                    <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                    <span>Signing in...</span>
                  </>
                ) : (
                  <>
                    <span>Sign In</span>
                    <ArrowRight className="h-5 w-5" />
                  </>
                )}
              </button>
            </form>
          </div>
        </div>

        {/* Right Side - Branding */}
        <div className={`hidden lg:flex flex-1 bg-gradient-to-br ${currentUserType.gradient} items-center justify-center p-12`}>
          <div className="max-w-md text-center">
            <Sparkles className="h-16 w-16 text-white mx-auto mb-6 opacity-90" />
            <h2 className="text-4xl font-bold text-white mb-4">
              Welcome to CampusConnect
            </h2>
            <p className="text-lg text-white/90 leading-relaxed">
              Your comprehensive platform for campus placements, internships, and career development.
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white">
      {/* Navigation */}
      <nav className="border-b border-neutral-200">
        <div className="max-w-7xl mx-auto px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className="p-2 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-xl">
                <GraduationCap className="h-6 w-6 text-white" />
              </div>
              <span className="text-xl font-bold text-neutral-900">CampusConnect</span>
            </div>
            <div className="hidden md:flex items-center space-x-8">
              <a href="#features" className="text-sm font-medium text-neutral-600 hover:text-neutral-900 transition-colors">
                Features
              </a>
              <a href="#about" className="text-sm font-medium text-neutral-600 hover:text-neutral-900 transition-colors">
                About
              </a>
              <a href="#contact" className="text-sm font-medium text-neutral-600 hover:text-neutral-900 transition-colors">
                Contact
              </a>
            </div>
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <section className="py-20 px-6">
        <div className="max-w-4xl mx-auto text-center">
          <div className="inline-flex items-center space-x-2 bg-blue-50 border border-blue-200 rounded-full px-4 py-2 mb-8">
            <Sparkles className="h-4 w-4 text-blue-600" />
            <span className="text-sm font-semibold text-blue-900">Professional Campus Placement Platform</span>
          </div>

          <h1 className="text-5xl md:text-6xl font-bold text-neutral-900 mb-6 leading-tight">
            Your Gateway to
            <span className="block mt-2 bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent">
              Career Success
            </span>
          </h1>

          <p className="text-xl text-neutral-600 mb-12 max-w-2xl mx-auto leading-relaxed">
            Streamline campus placements with our comprehensive platform. Track applications, connect with mentors, and manage recruitment efficiently.
          </p>
        </div>
      </section>

      {/* User Type Selection */}
      <section className="pb-20 px-6">
        <div className="max-w-5xl mx-auto">
          <div className="text-center mb-12">
            <h2 className="text-3xl font-bold text-neutral-900 mb-3">Choose Your Portal</h2>
            <p className="text-neutral-600">Select your role to access the platform</p>
          </div>

          <div className="grid md:grid-cols-3 gap-6">
            {userTypes.map((userType) => {
              const Icon = userType.icon;
              return (
                <button
                  key={userType.id}
                  onClick={() => {
                    setSelectedUserType(userType.id);
                    setShowLogin(true);
                  }}
                  className="group relative bg-white border-2 border-neutral-200 rounded-2xl p-8 hover:border-neutral-300 hover:shadow-xl transition-all duration-300 text-left"
                >
                  <div className={`inline-flex p-4 rounded-2xl bg-gradient-to-br ${userType.gradient} mb-6 group-hover:scale-110 transition-transform duration-300`}>
                    <Icon className="h-8 w-8 text-white" />
                  </div>

                  <h3 className="text-2xl font-bold text-neutral-900 mb-2">
                    {userType.title}
                  </h3>

                  <p className="text-neutral-600 mb-6">
                    {userType.description}
                  </p>

                  <div className="flex items-center text-blue-600 font-semibold group-hover:translate-x-2 transition-transform">
                    <span className="mr-2">Get Started</span>
                    <ArrowRight className="h-5 w-5" />
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      </section>

      {/* Features Section */}
      <section id="features" className="py-20 px-6 bg-neutral-50 border-t border-neutral-200">
        <div className="max-w-5xl mx-auto">
          <div className="text-center mb-16">
            <h2 className="text-3xl font-bold text-neutral-900 mb-3">Why Choose CampusConnect</h2>
            <p className="text-neutral-600">Enterprise-grade features for modern campus placement</p>
          </div>

          <div className="grid md:grid-cols-3 gap-8">
            {features.map((feature, index) => {
              const Icon = feature.icon;
              return (
                <div key={index} className="bg-white border border-neutral-200 rounded-2xl p-8 hover:shadow-lg transition-shadow">
                  <div className="inline-flex p-3 bg-blue-50 rounded-xl mb-4">
                    <Icon className="h-6 w-6 text-blue-600" />
                  </div>
                  <h3 className="text-xl font-bold text-neutral-900 mb-2">
                    {feature.title}
                  </h3>
                  <p className="text-neutral-600">
                    {feature.description}
                  </p>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="bg-neutral-900 text-white py-12 px-6">
        <div className="max-w-5xl mx-auto">
          <div className="flex flex-col md:flex-row items-center justify-between">
            <div className="flex items-center space-x-3 mb-4 md:mb-0">
              <div className="p-2 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-xl">
                <GraduationCap className="h-5 w-5 text-white" />
              </div>
              <span className="text-lg font-bold">CampusConnect</span>
            </div>
            <div className="flex items-center space-x-6 text-sm text-neutral-400">
              <a href="#" className="hover:text-white transition-colors">Privacy</a>
              <a href="#" className="hover:text-white transition-colors">Terms</a>
              <a href="#" className="hover:text-white transition-colors">Support</a>
            </div>
          </div>
          <div className="mt-8 pt-8 border-t border-neutral-800 text-center text-sm text-neutral-500">
            © 2025 CampusConnect. All rights reserved.
          </div>
        </div>
      </footer>
    </div>
  );
};

export default ProfessionalLogin;
